odelsRepoIntegrationEnabled:!1,isMarketplaceEnabled:!0}},dataUpdateCount:1,dataUpdatedAt:1793127182063,error:null,errorUpdateCount:0,errorUpdatedAt:0,fetchFailureCount:0,fetchFailureReason:null,fetchMeta:null,isInvalidated:!1,status:"success",fetchStatus:"idle"},queryKey:$R[260],queryHash:"[\"code-view\",\"codeViewBlobLayoutRoute\",\"\",\"mainQuery\",{\"pathname\":\"/microsoft/sql-server-samples/_layout/master/samples/databases/northwind-pubs/instpubs.sql\"}]"},$R[406]={dehydratedAt:1793127182063,state:$R[407]={data:$R[408]={payload:$R[409]={"codeViewBlobLayoutRoute.StyledBlob":$R[410]={rawLines:$R[411]=["/*                                                                        */","/*              InstPubs.SQL - Creates the Pubs database                  */","/*                                                                        */","/*","** Copyright Microsoft, Inc. 1994 - 2000","** All Rights Reserved.","*/","","SET NOCOUNT ON","GO","","set nocount    on","set dateformat mdy","","USE master","","declare @dttm varchar(55)","select  @dttm=convert(varchar,getdate(),113)","raiserror('Beginning InstPubs.SQL at %s ....',1,1,@dttm) with nowait","","GO","","if exists (select * from sysdatabases where name='pubs')","begin","  raiserror('Dropping existing pubs database ....',0,1)","  DROP database pubs","end","GO","","CHECKPOINT","go","","raiserror('Creating pubs database....',0,1)","go","/*","   Use default size with autogrow","*/","","CREATE DATABASE pubs","GO","","CHECKPOINT","","GO","","USE pubs","","GO","","if db_name() \x3C> 'pubs'","   raiserror('Error in InstPubs.SQL, ''USE pubs'' failed!  Killing the SPID now.'","            ,22,127) with log","","GO","","if CAST(SERVERPROPERTY('ProductMajorVersion') AS INT)\x3C12","BEGIN","  exec sp_dboption 'pubs','trunc. log on chkpt.','true'","  exec sp_dboption 'pubs','select into/bulkcopy','true'","END","ELSE ALTER DATABASE [pubs] SET RECOVERY SIMPLE WITH NO_WAIT","GO","","execute sp_addtype id      ,'varchar(11)' ,'NOT NULL'","execute sp_addtype tid     ,'varchar(6)'  ,'NOT NULL'","execute sp_addtype empid   ,'char(9)'     ,'NOT NULL'","","raiserror('Now at the create table section ....',0,1)","","GO","CREATE TABLE authors (","    au_id          CHAR(11) CHECK (au_id LIKE '[0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9][0-9][0-9]')","                    CONSTRAINT UPKCL_auidind PRIMARY KEY CLUSTERED,","    au_lname       VARCHAR(40) NOT NULL,","    au_fname       VARCHAR(20) NOT NULL,","    phone          CHAR(12) NOT NULL DEFAULT ('UNKNOWN'),","    address        VARCHAR(40) NULL,","    city           VARCHAR(20) NULL,","    state          CHAR(2) NULL,","    zip            CHAR(5) NULL CHECK (zip LIKE '[0-9][0-9][0-9][0-9][0-9]'),","    contract       BIT NOT NULL",");","","GO","","CREATE TABLE publishers (","    pub_id         CHAR(4) NOT NULL ","                    CONSTRAINT UPKCL_pubind PRIMARY KEY CLUSTERED ","                    CHECK (pub_id IN ('1389', '0736', '0877', '1622', '1756') OR pub_id LIKE '99[0-9][0-9]'),","    pub_name       VARCHAR(40) NULL,","    city           VARCHAR(20) NULL,","    state          CHAR(2) NULL,","    country        VARCHAR(30) NULL DEFAULT('USA')",");","","GO","","CREATE TABLE titles (","    title_id       CHAR(6) CONSTRAINT UPKCL_titleidind PRIMARY KEY CLUSTERED,","    title          VARCHAR(80) NOT NULL,","    type           CHAR(12) NOT NULL DEFAULT ('UNDECIDED'),","    pub_id         CHAR(4) NULL REFERENCES publishers(pub_id),","    price          MONEY NULL,","    advance        MONEY NULL,","    royalty        INT NULL,","    ytd_sales      INT NULL,","    notes          VARCHAR(200) NULL,","    pubdate        DATETIME NOT NULL DEFAULT (GETDATE())",");","","GO","","CREATE TABLE titleauthor (","    au_id          CHAR(11) REFERENCES authors(au_id),","    title_id       CHAR(6) REFERENCES titles(title_id),","    au_ord         TINYINT NULL,","    royaltyper     INT NULL,","    CONSTRAINT UPKCL_taind PRIMARY KEY CLUSTERED(au_id, title_id)",");","","GO","","CREATE TABLE stores (","    stor_id        CHAR(4) NOT NULL CONSTRAINT UPK_storeid PRIMARY KEY CLUSTERED,","    stor_name      VARCHAR(40) NULL,","    stor_address   VARCHAR(40) NULL,","    city           VARCHAR(20) NULL,","    state          CHAR(2) NULL,","    zip            CHAR(5) NULL",");","","GO","","CREATE TABLE sales (","    stor_id        CHAR(4) NOT NULL REFERENCES stores(stor_id),","    ord_num        VARCHAR(20) NOT NULL,","    ord_date       DATETIME NOT NULL,","    qty            SMALLINT NOT NULL,","    payterms       VARCHAR(12) NOT NULL,","    title_id       CHAR(6) REFERENCES titles(title_id),","    CONSTRAINT UPKCL_sales PRIMARY KEY CLUSTERED (stor_id, ord_num, title_id)",");","","GO","","CREATE TABLE roysched (","    title_id       CHAR(6) REFERENCES titles(title_id),","    lorange        INT NULL,","    hirange        INT NULL,","    royalty        INT NULL",");","","GO","","CREATE TABLE discounts (","    discounttype   VARCHAR(40) NOT NULL,","    stor_id        CHAR(4) NULL REFERENCES stores(stor_id),","    lowqty         SMALLINT NULL,","    highqty        SMALLINT NULL,","    discount       DECIMAL(4,2) NOT NULL",");","","GO","","CREATE TABLE jobs (","    job_id         SMALLINT IDENTITY(1,1) PRIMARY KEY CLUSTERED,","    job_desc       VARCHAR(50) NOT NULL DEFAULT 'New Position - title not formalized yet',","    min_lvl        TINYINT NOT NULL CHECK (min_lvl >= 10),","    max_lvl        TINYINT NOT NULL CHECK (max_lvl \x3C= 250)",");","","GO","","CREATE TABLE pub_info (","    pub_id         CHAR(4) NOT NULL REFERENCES publishers(pub_id) CONSTRAINT UPKCL_pubinfo PRIMARY KEY CLUSTERED,","    logo           IMAGE NULL,","    pr_info        TEXT NULL",");","","GO","","CREATE TABLE employee (","    emp_id         CHAR(10) CONSTRAINT PK_emp_id PRIMARY KEY NONCLUSTERED CHECK (","                    emp_id LIKE '[A-Z][A-Z][A-Z][1-9][0-9][0-9][0-9][0-9][FM]' OR ","                    emp_id LIKE '[A-Z]-[A-Z][1-9][0-9][0-9][0-9][0-9][FM]'),","    fname          VARCHAR(20) NOT NULL,","    minit          CHAR(1) NULL,","    lname          VARCHAR(30) NOT NULL,","    job_id         SMALLINT NOT NULL DEFAULT 1 REFERENCES jobs(job_id),","    job_lvl        TINYINT DEFAULT 10,","    pub_id         CHAR(4) NOT NULL DEFAULT ('9952') REFERENCES publishers(pub_id),","    hire_date      DATETIME NOT NULL DEFAULT (GETDATE())",");","","GO","","raiserror('Now at the create trigger section ...',0,1)","","GO","","CREATE TRIGGER employee_insupd","ON employee","FOR insert, UPDATE","AS","--Get the range of level for this job type from the jobs table.","declare @min_lvl tinyint,","   @max_lvl tinyint,","   @emp_lvl tinyint,","   @job_id smallint","select @min_lvl = min_lvl,","   @max_lvl = max_lvl,","   @emp_lvl = i.job_lvl,","   @job_id = i.job_id","from employee e, jobs j, inserted i","where e.emp_id = i.emp_id AND i.job_id = j.job_id","IF (@job_id = 1) and (@emp_lvl \x3C> 10)","begin","   raiserror ('Job id 1 expects the default level of 10.',16,1)","   ROLLBACK TRANSACTION","end","ELSE","IF NOT (@emp_lvl BETWEEN @min_lvl AND @max_lvl)","begin","   raiserror ('The level for job_id:%d should be between %d and %d.',","      16, 1, @job_id, @min_lvl, @max_lvl)","   ROLLBACK TRANSACTION","end","","GO","","raiserror('Now at the inserts to authors ....',0,1)","","GO","","insert authors","   values('409-56-7008', 'Bennet', 'Abraham', '415 658-9932',","   '6223 Bateman St.', 'Berkeley', 'CA', '94705', 1)","insert authors","   values('213-46-8915', 'Green', 'Marjorie', '415 986-7020',","   '309 63rd St. #411', 'Oakland', 'CA', '94618', 1)","insert authors","   values('238-95-7766', 'Carson', 'Cheryl', '415 548-7723',","   '589 Darwin Ln.', 'Berkeley', 'CA', '94705', 1)","insert authors","   values('998-72-3567', 'Ringer', 'Albert', '801 826-0752',","   '67 Seventh Av.', 'Salt Lake City', 'UT', '84152', 1)","insert authors","   values('899-46-2035', 'Ringer', 'Anne', '801 826-0752',","   '67 Seventh Av.', 'Salt Lake City', 'UT